package test.prok;

import java.io.File;
import java.util.ArrayList;
import java.util.Arrays;

import fileIO.ByteFile;
import fileIO.ByteStreamWriter;
import fileIO.FileFormat;
import parse.LineParser1;
import prok.NcrnaCalibrationPrep;
import prok.NcrnaReviewFeatureContext;
import prok.NcrnaReviewUnion;
import prok.RrnaResourceIO;
import stream.Read;
import stream.Writer;
import stream.WriterFactory;

/** Exact source-row accounting, parent ambiguity, circular geometry and source failures.
 * Hashes are generated by the supplied canonical sha80 executable, never fabricated.
 * @author Brian, Ganyu
 */
public final class NcrnaReviewFeatureContextTest {

	public static void main(String[] args)throws Exception{
		require(args.length==2, "Supply a fresh fixture directory and canonical sha80 executable");
		final File root=new File(args[0]);require(!root.exists() && root.mkdirs(), "Fixture must not overwrite existing evidence");
		final String base=root.getAbsolutePath(), fasta=base+"/source.fa", gff=base+"/source.gff", roster=base+"/roster.tsv", loci=base+"/loci.tsv";
		fasta(fasta, "chr", "circle");
		final String[] annotations={
			"##gff-version 3",
			gff("chr", "region", 1, 100, ".", "ID=region;Is_circular=false"),
			gff("chr", "gene", 10, 30, "+", "ID=g0;Name=parent"),
			gff("chr", "CDS", 12, 18, "+", "ID=cds0;Parent=g0;product=protein"),
			gff("chr", "ncRNA", 15, 25, "-", "ID=n0;Dbxref=Rfam:RF00005"),
			gff("chr", "regulatory", 19, 22, "+", "ID=b0;Dbxref=GeneID:1,RFAM:RF00174;product=cobalamin riboswitch"),
			gff("chr", "gene", 75, 90, "?", "ID=uncertain;partial=true"),
			gff("chr", "ncRNA", 35, 40, "-", "ID=b1;Dbxref=Rfam:RF00174"),
			gff("circle", "CDS", 95, 110, "-", "ID=wrap;product=origin-spanning protein"),
			gff("circle", "ncRNA", 97, 99, "+", "ID=not_target;Dbxref=Rfam:RF001740"),
			gff("circle", "region", 1, 100, ".", "ID=circle;Is_circular=true"),
			"##FASTA", ">ignored_embedded_sequence", "AAAA"};
		write(gff, annotations);
		write(roster, NcrnaCalibrationPrep.ROSTER_HEADER, rosterRow("g", "a", gff, fasta, 2));
		write(loci, NcrnaReviewUnion.LOCUS_HEADER,
			locus("r0", "chr", 11, 20, "+", fasta), locus("r1", "chr", 50, 60, "-", fasta),
			locus("r2", "chr", 80, 85, "+", fasta), locus("r3", "circle", 1, 8, "+", fasta),
			locus("r4", "circle", 96, 100, "-", fasta), locus("r5", "chr", 35, 40, "-", fasta));
		final String gh=base+"/gff.sha80", fh=base+"/fasta.sha80";
		write(gh, hash(args[1], gff)+'\t'+gff);write(fh, hash(args[1], fasta)+'\t'+fasta);
		run(loci, roster, gh, fh, base+"/good", 6, 1, 2);
		final ArrayList<String> rows=lines(base+"/good.loci.tsv"), overlaps=lines(base+"/good.overlaps.tsv"), summary=lines(base+"/good.summary.tsv");
		require(rows.size()==7 && overlaps.size()==16, "Six predictions retain nine feature and six region overlap rows");
		final LineParser1 p=new LineParser1('\t');
		p.set(rows.get(1).getBytes(java.nio.charset.StandardCharsets.UTF_8));
		require(p.terms()==26 && p.parseInt(7)==10 && p.parseInt(8)==189 && p.parseInt(9)==-179
			&& Math.abs(p.parseDouble(10)-10.0/189)<0.000001 && p.parseInt(11)==4 && p.parseInt(12)==1
			&& p.parseInt(13)==1 && p.parseInt(14)==1 && p.parseInt(15)==1 && p.parseInt(16)==1
			&& p.parseInt(18)==3 && p.parseInt(19)==1, "All gene/CDS/target/other-RNA overlaps and opposite strand survive with exact length metrics");
		checkContext(rows.get(2), "INTERGENIC", 0, 0, 0, 0);
		checkContext(rows.get(3), "PARENT_ONLY_OR_AMBIGUOUS", 1, 0, 0, 1);
		checkContext(rows.get(4), "FEATURE_OVERLAP", 1, 0, 1, 0);
		checkContext(rows.get(5), "FEATURE_OVERLAP", 2, 1, 1, 0);
		p.set(rows.get(5).getBytes(java.nio.charset.StandardCharsets.UTF_8));require(p.parseInt(14)==0 && p.parseInt(15)==1, "RF001740 must not match RF00174");
		checkContext(rows.get(6), "FEATURE_OVERLAP", 1, 1, 0, 0);
		boolean low=false, high=false;
		for(int i=1;i<overlaps.size();i++){
			p.set(overlaps.get(i).getBytes(java.nio.charset.StandardCharsets.UTF_8));require(p.terms()==22, "Every overlapping original GFF row keeps all nine original fields");
			if(p.termEquals("r3", 0) && p.termEquals("CDS", 8)){
				require(p.parseInt(10)==8 && p.termEquals("OPPOSITE", 11) && p.termEquals("true", 12)
					&& p.parseInt(16)==95 && p.parseInt(17)==110 && p.termEquals("ID=wrap;product=origin-spanning protein", 21), "Circular overlap must retain the unrolled source coordinates and raw attributes");low=true;
			}
			if(p.termEquals("r4", 0) && p.termEquals("CDS", 8)){require(p.parseInt(10)==5, "Upper circular segment overlap is exact");high=true;}
		}
		require(low && high && summary.get(1).equals("6\t1\t2\t9\t6\t1\t1\tSOURCE_CONTEXT_NOT_CM_ADMISSION_OR_FP_VERDICT"), "Every context is accounted without turning metadata into conflicts or inventing an adjudication");

		write(base+"/foreign_loci.tsv", NcrnaReviewUnion.LOCUS_HEADER, locus("bad", "chr", 1, 5, "+", fasta).replace("\tg\ta\t", "\tg\tforeign\t"));
		fails(base+"/foreign_loci.tsv", roster, gh, fh, base+"/bad_binding", 1, 1, 2, "Foreign prediction");
		write(base+"/missing_loci.tsv", NcrnaReviewUnion.LOCUS_HEADER, locus("missing", "absent", 1, 5, "+", fasta));
		fails(base+"/missing_loci.tsv", roster, gh, fh, base+"/bad_missing", 1, 1, 2, "missing from original");
		write(base+"/unbound.sha80", hash(args[1], fasta)+'\t'+fasta);
		// A valid manifest for a different file must not satisfy the source GFF binding.
		fails(loci, roster, base+"/unbound.sha80", fh, base+"/bad_hashes", 6, 1, 2, "verified source hashes required");
		final String linear=base+"/linear.gff";write(linear, gff("circle", "CDS", 95, 110, "-", "ID=wrap"));
		write(base+"/linear_roster.tsv", NcrnaCalibrationPrep.ROSTER_HEADER, rosterRow("g", "a", linear, fasta, 2));
		write(base+"/linear.sha80", hash(args[1], linear)+'\t'+linear);
		fails(loci, base+"/linear_roster.tsv", base+"/linear.sha80", fh, base+"/bad_topology", 6, 1, 2, "explicit circular");
		final String foreign=base+"/foreign.gff";write(foreign, gff("absent", "CDS", 1, 5, "+", "ID=foreign"));
		write(base+"/foreign_roster.tsv", NcrnaCalibrationPrep.ROSTER_HEADER, rosterRow("g", "a", foreign, fasta, 2));
		write(base+"/foreign.sha80", hash(args[1], foreign)+'\t'+foreign);
		fails(loci, base+"/foreign_roster.tsv", base+"/foreign.sha80", fh, base+"/bad_foreign_gff", 6, 1, 2, "GFF contig absent or foreign");
		System.out.println("NCRNA_REVIEW_FEATURE_CONTEXT_TEST_PASS");
	}
	private static void run(String loci, String roster, String gh, String fh, String out, int expected, int genomes, int contigs){
		assert(expected>0):"Fixture declares its full prediction population";
		NcrnaReviewFeatureContext.main(new String[]{"loci="+loci, "roster="+roster, "gffhashes="+gh, "fastahashes="+fh,
			"outprefix="+out, "expected="+expected, "genomes="+genomes, "contigs="+contigs, "family=cobalamin", "modelid=RF00174", "modellength=189"});
	}
	private static void fails(String loci, String roster, String gh, String fh, String out, int expected, int genomes, int contigs, String message){
		boolean failed=false;
		try{run(loci, roster, gh, fh, out, expected, genomes, contigs);}catch(IllegalArgumentException e){failed=e.getMessage().contains(message);}
		require(failed && !new File(out+".summary.tsv").exists() && !new File(out+".overlaps.tsv").exists(), "Invalid source must fail before output: "+message);
	}
	private static void checkContext(String row, String context, int features, int same, int opposite, int unknown){
		final LineParser1 p=new LineParser1('\t');p.set(row.getBytes(java.nio.charset.StandardCharsets.UTF_8));
		require(p.termEquals(context, 21) && p.parseInt(11)==features && p.parseInt(18)==same && p.parseInt(19)==opposite && p.parseInt(20)==unknown, "Exact source context and strand counts changed");
	}
	private static String locus(String id, String contig, int start, int stop, String strand, String fasta){
		assert(start>0 && stop>=start && stop<=100):"Fixture loci lie inside their actual 100-base contig";
		return id+"\tg\ta\t"+fasta+'\t'+contig+"\tcobalamin\t"+strand+'\t'+start+'\t'+stop+"\t100\t0\t0\t"+(stop-start+1)+"\tPREDICTION_UNRESOLVED";
	}
	private static String rosterRow(String genome, String assembly, String gff, String fasta, int contigs){
		assert(contigs>0):"Fixture roster declares source dimensions";
		return "0\t"+genome+'\t'+assembly+"\t1\tbacteria\tp\t"+gff+'\t'+fasta+"\t0\t"+(100*contigs)+'\t'+contigs;
	}
	private static String gff(String contig, String type, int start, int stop, String strand, String attrs){
		assert(stop>=start):"Source coordinates may cross a circular origin but may not reverse";
		return contig+"\tFixture\t"+type+'\t'+start+'\t'+stop+"\t.\t"+strand+"\t.\t"+attrs;
	}
	private static void fasta(String path, String... names){
		assert(names.length>0):"Native fixture FASTA contains the bound contigs";
		final Writer out=WriterFactory.makeWriter(FileFormat.testOutput(path, FileFormat.FASTA, null, true, false, false, true), null, 1);out.start();
		try{
			final ArrayList<Read> reads=new ArrayList<Read>();
			for(String name:names){final byte[] bases=new byte[100];Arrays.fill(bases, (byte)'A');reads.add(new Read(bases, null, name, reads.size(), false));}
			out.add(reads, 0);
		}finally{require(!out.poisonAndWait(), "Fixture FASTA output failed");}
	}
	private static String hash(String executable, String path)throws Exception{
		assert(executable!=null && path!=null):"Fixture provenance comes from the canonical sha80 tool";
		final File output=new File(path+".hash.txt");
		final Process process=new ProcessBuilder(executable, path).redirectOutput(output).redirectError(ProcessBuilder.Redirect.INHERIT).start();
		require(process.waitFor()==0, "Canonical sha80 failed for fixture");final ArrayList<String> rows=lines(output.getPath());
		require(rows.size()==1 && rows.get(0).matches("[0-9a-f]{20}"), "Canonical sha80 must emit exactly one valid digest");return rows.get(0);
	}
	private static void write(String path, String... rows){
		assert(rows.length>0):"Fixture text has explicit content";
		final ByteStreamWriter out=RrnaResourceIO.writer(path);try{for(String row:rows){out.println(row);}}finally{RrnaResourceIO.finish(out);}
	}
	private static ArrayList<String> lines(String path){
		final ByteFile in=RrnaResourceIO.open(path);final ArrayList<String> out=new ArrayList<String>();
		try{for(byte[] row;(row=in.nextLine())!=null;){out.add(new String(row, java.nio.charset.StandardCharsets.UTF_8));}}
		finally{require(!in.close(), "Fixture evidence read failed");}return out;
	}
	private static void require(boolean ok, String why){if(!ok){throw new AssertionError(why);}}
}
